@startuml
class Customer {
  +name : string
  +phoneNumber : string
}

class Table {
  +numberOfSeats : int
  +isSmoking : boolean
}

class Reservation {
  +day : date
  +time : time
  +numberOfPeople : int
}

class Waiter {
  +name : string
  +yearsOfService : int
}

class Bill {
  +totalAmount : float
}

class Dish {
  +name : string
  +unitPrice : float
}

class BillLine {
  +quantity : int
}

Customer "1" -- "*" Reservation : makes
Reservation "*" -- "1..*" Table : is assigned to
Waiter "1" -- "*" Customer : serves
Customer "1" -- "*" Bill : receives
Bill "1" *-- "1..*" BillLine : made up of
BillLine "*" -- "1" Dish : includes
@enduml

